/**
 * Low-level helpers over the trusted DbSession contract.
 *
 * All SQL here is generated by trusted code only. Values are either
 * identifier-escaped or passed as placeholders; user/AI supplied strings are
 * never concatenated.
 */
import { randomBytes } from 'node:crypto'
import type { DbSession, Services } from '@main/service-contracts'
import type { Id } from '@shared/types'
import { AppError, toAppError } from '@main/util/errors'
import type { ServerFlavor, TableMeta } from './internal-types'
import { ident, qualified } from './sqlformat'

export async function openSession(
  services: Services,
  connectionId: Id,
  database?: string
): Promise<DbSession> {
  try {
    return await services.connections.openSession(connectionId, database)
  } catch (e) {
    throw toAppError(e, 'CONNECTION_FAILED')
  }
}

export async function withSession<T>(
  services: Services,
  connectionId: Id,
  database: string | undefined,
  fn: (session: DbSession) => Promise<T>
): Promise<T> {
  const session = await openSession(services, connectionId, database)
  try {
    return await fn(session)
  } finally {
    try {
      await session.release()
    } catch {
      /* releasing a broken session must not mask the real error */
    }
  }
}

export function scalarString(value: unknown): string {
  if (value === null || value === undefined) return ''
  if (Buffer.isBuffer(value)) return value.toString('utf8')
  return String(value)
}

export function scalarNumber(value: unknown): number {
  const n = typeof value === 'number' ? value : Number(scalarString(value))
  return Number.isFinite(n) ? n : 0
}

export async function getServerInfo(
  session: DbSession
): Promise<{ version: string; flavor: ServerFlavor; charset: string }> {
  const version = scalarString(session.serverVersion || '')
  const flavor: ServerFlavor = session.serverFlavor ?? 'unknown'
  let charset = session.charset || 'utf8mb4'
  try {
    const r = await session.rawQuery<Record<string, unknown>>(
      'SELECT @@character_set_database AS charset'
    )
    const v = scalarString(r.rows[0]?.charset)
    if (v) charset = v
  } catch {
    /* fall back to session charset */
  }
  return { version, flavor, charset }
}

export async function databaseExists(session: DbSession, database: string): Promise<boolean> {
  const r = await session.rawQuery<Record<string, unknown>>(
    'SELECT SCHEMA_NAME AS name FROM information_schema.SCHEMATA WHERE SCHEMA_NAME = ?',
    [database]
  )
  return r.rows.length > 0
}

export async function databaseCharset(session: DbSession, database: string): Promise<string> {
  const r = await session.rawQuery<Record<string, unknown>>(
    'SELECT DEFAULT_CHARACTER_SET_NAME AS c FROM information_schema.SCHEMATA WHERE SCHEMA_NAME = ?',
    [database]
  )
  return scalarString(r.rows[0]?.c) || 'utf8mb4'
}

export async function listObjects(
  session: DbSession,
  database: string
): Promise<{ name: string; type: 'table' | 'view' }[]> {
  const r = await session.rawQuery<Record<string, unknown>>(
    `SELECT TABLE_NAME AS name, TABLE_TYPE AS type
       FROM information_schema.TABLES
      WHERE TABLE_SCHEMA = ?
      ORDER BY TABLE_NAME`,
    [database]
  )
  return r.rows.map((row) => {
    const typeRaw = scalarString(row.type).toUpperCase()
    return {
      name: scalarString(row.name),
      type: typeRaw.includes('VIEW') ? ('view' as const) : ('table' as const)
    }
  })
}

export async function tableExists(
  session: DbSession,
  database: string,
  table: string
): Promise<boolean> {
  const r = await session.rawQuery<Record<string, unknown>>(
    `SELECT TABLE_NAME AS name FROM information_schema.TABLES
      WHERE TABLE_SCHEMA = ? AND TABLE_NAME = ?`,
    [database, table]
  )
  return r.rows.length > 0
}

const TABLE_META_CACHE: unique symbol = Symbol('table-meta-cache')

type SessionWithCache = DbSession & { [TABLE_META_CACHE]?: Map<string, TableMeta> }

/** Reads columns / primary key / triggers from information_schema. */
export async function getTableMeta(
  session: DbSession,
  database: string,
  table: string
): Promise<TableMeta> {
  const cacheOwner = session as SessionWithCache
  let cache = cacheOwner[TABLE_META_CACHE]
  if (!cache) {
    cache = new Map()
    cacheOwner[TABLE_META_CACHE] = cache
  }
  const key = `${database}.${table}`
  const cached = cache.get(key)
  if (cached) return cached

  const cols = await session.rawQuery<Record<string, unknown>>(
    `SELECT COLUMN_NAME AS name, DATA_TYPE AS dataType, COLUMN_TYPE AS columnType,
            EXTRA AS extra, GENERATION_EXPRESSION AS generationExpr
       FROM information_schema.COLUMNS
      WHERE TABLE_SCHEMA = ? AND TABLE_NAME = ?
      ORDER BY ORDINAL_POSITION`,
    [database, table]
  )
  const pk = await session.rawQuery<Record<string, unknown>>(
    `SELECT COLUMN_NAME AS name FROM information_schema.STATISTICS
      WHERE TABLE_SCHEMA = ? AND TABLE_NAME = ? AND INDEX_NAME = 'PRIMARY'
      ORDER BY SEQ_IN_INDEX`,
    [database, table]
  )
  const trig = await session.rawQuery<Record<string, unknown>>(
    `SELECT TRIGGER_NAME AS name FROM information_schema.TRIGGERS
      WHERE EVENT_OBJECT_SCHEMA = ? AND EVENT_OBJECT_TABLE = ?
      ORDER BY TRIGGER_NAME`,
    [database, table]
  )
  const engineRow = await session.rawQuery<Record<string, unknown>>(
    `SELECT ENGINE AS engine, TABLE_TYPE AS type FROM information_schema.TABLES
      WHERE TABLE_SCHEMA = ? AND TABLE_NAME = ?`,
    [database, table]
  )
  const meta: TableMeta = {
    name: table,
    type: scalarString(engineRow.rows[0]?.type).toUpperCase().includes('VIEW') ? 'view' : 'table',
    engine: scalarString(engineRow.rows[0]?.engine) || null,
    columns: cols.rows.map((row) => {
      const extra = scalarString(row.extra).toUpperCase()
      const generationExpr = scalarString(row.generationExpr)
      return {
        name: scalarString(row.name),
        dataType: scalarString(row.dataType).toLowerCase(),
        columnType: scalarString(row.columnType),
        generated: generationExpr.length > 0 || extra.includes('GENERATED'),
        autoIncrement: extra.includes('AUTO_INCREMENT')
      }
    }),
    primaryKey: pk.rows.map((row) => scalarString(row.name)),
    triggers: trig.rows.map((row) => scalarString(row.name))
  }
  cache.set(key, meta)
  return meta
}

const INTEGER_TYPES = new Set([
  'tinyint',
  'smallint',
  'mediumint',
  'int',
  'integer',
  'bigint'
])

/** Returns the single integer primary key column, or null (pagination fallback). */
export function singleIntegerPk(meta: TableMeta): string | null {
  if (meta.primaryKey.length !== 1) return null
  const name = meta.primaryKey[0]
  const col = meta.columns.find((c) => c.name === name)
  if (!col) return null
  if (!INTEGER_TYPES.has(col.dataType)) return null
  return name
}

export function insertableColumns(meta: TableMeta): string[] {
  return meta.columns.filter((c) => !c.generated).map((c) => c.name)
}

export async function captureCreateStatements(
  session: DbSession,
  database: string,
  objects: { name: string; type: 'table' | 'view' }[]
): Promise<Record<string, string>> {
  const result: Record<string, string> = {}
  for (const object of objects) {
    try {
      const verb = object.type === 'view' ? 'VIEW' : 'TABLE'
      const r = await session.rawQuery<Record<string, unknown>>(
        `SHOW CREATE ${verb} ${qualified(database, object.name)}`
      )
      const row = r.rows[0] ?? {}
      // SHOW CREATE TABLE returns [Table, Create Table]; VIEW returns [View, Create View, ...]
      const key = Object.keys(row).find((k) => /create (table|view)/i.test(k))
      const sql = key ? scalarString(row[key]) : ''
      if (sql) result[object.name] = sql
    } catch {
      /* missing object: caller decides what that means */
    }
  }
  return result
}

export async function countAllRows(
  session: DbSession,
  database: string,
  table: string
): Promise<number> {
  const r = await session.rawQuery<Record<string, unknown>>(
    `SELECT COUNT(*) AS c FROM ${qualified(database, table)}`
  )
  return scalarNumber(r.rows[0]?.c)
}

export function tempDatabaseName(prefix: string): string {
  const rand = randomBytes(4).toString('hex')
  const safePrefix = prefix.replace(/[^a-zA-Z0-9_]/g, '_').slice(0, 40)
  return `${safePrefix}_${Date.now().toString(36)}_${rand}`.toLowerCase()
}

/** Creates an empty database with the source database' default charset. */
export async function createDatabase(
  session: DbSession,
  database: string,
  charset: string
): Promise<void> {
  const safeCharset = /^[a-zA-Z0-9_]+$/.test(charset) ? charset : 'utf8mb4'
  await session.rawQuery(
    `CREATE DATABASE ${ident(database)} CHARACTER SET ${safeCharset} COLLATE ${safeCollation(safeCharset)}`
  )
}

function safeCollation(charset: string): string {
  if (charset === 'utf8mb4') return 'utf8mb4_general_ci'
  if (charset === 'utf8') return 'utf8_general_ci'
  if (charset === 'latin1') return 'latin1_swedish_ci'
  return `${charset}_general_ci`
}

export async function dropDatabase(session: DbSession, database: string): Promise<void> {
  await session.rawQuery(`DROP DATABASE IF EXISTS ${ident(database)}`)
}

export async function listTables(session: DbSession, database: string): Promise<string[]> {
  const r = await session.rawQuery<Record<string, unknown>>(
    `SELECT TABLE_NAME AS name FROM information_schema.TABLES
      WHERE TABLE_SCHEMA = ? AND TABLE_TYPE = 'BASE TABLE'
      ORDER BY TABLE_NAME`,
    [database]
  )
  return r.rows.map((row) => scalarString(row.name))
}

export async function listLiveColumns(
  session: DbSession,
  database: string,
  table: string
): Promise<string[]> {
  const r = await session.rawQuery<Record<string, unknown>>(
    `SELECT COLUMN_NAME AS name FROM information_schema.COLUMNS
      WHERE TABLE_SCHEMA = ? AND TABLE_NAME = ?
      ORDER BY ORDINAL_POSITION`,
    [database, table]
  )
  return r.rows.map((row) => scalarString(row.name))
}

/** Raises a typed error when the database is not reachable/writable. */
export async function assertDatabaseReachable(session: DbSession, database: string): Promise<void> {
  if (!(await databaseExists(session, database))) {
    throw new AppError('NOT_FOUND', `数据库 ${database} 不存在`, {
      hint: '请检查连接和数据库名'
    })
  }
}

export function escapeIdentifier(name: string): string {
  return ident(name)
}
